class Solution { vector<vector<int>> graph;vector<int> nums;int target;bool valid;int dfs(int node,int parent){int sum=nums[node];for(int next:graph[node])if(next!=parent)sum+=dfs(next,node);if(sum>target)valid=false;return sum==target?0:sum;}public:int componentValue(vector<int>& values,vector<vector<int>>& edges){nums=values;int n=nums.size(),total=accumulate(nums.begin(),nums.end(),0);graph.assign(n,{});for(auto& edge:edges){graph[edge[0]].push_back(edge[1]);graph[edge[1]].push_back(edge[0]);}for(int components=n;components>=1;--components)if(total%components==0){target=total/components;valid=true;if(dfs(0,-1)==0&&valid)return components-1;}return 0;} };
